const construire_le_mail = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Construire le mail', parameters: { jsCode: 'const d = $(\'Statistiques par marque\').first().json;\n\nfunction echapper(v) { return String(v === null || v === undefined ? \'\' : v).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\'); }\nfunction cell(v, suffixe) { return (v === null || v === undefined || v === \'\') ? \'-\' : echapper(v) + (suffixe || \'\'); }\n\nconst lignesHtml = (d.stats || []).map((s) =>\n  \'<tr><td style="padding:6px 10px;border:1px solid #ddd"><strong>\' + echapper(s.marque) + \'</strong></td>\' +\n  \'<td style="padding:6px 10px;border:1px solid #ddd;text-align:right">\' + s.produits + \'</td>\' +\n  \'<td style="padding:6px 10px;border:1px solid #ddd;text-align:right">\' + s.promotions + \'</td>\' +\n  \'<td style="padding:6px 10px;border:1px solid #ddd;text-align:right">\' + cell(s.tauxPromo, \' %\') + \'</td>\' +\n  \'<td style="padding:6px 10px;border:1px solid #ddd;text-align:right">\' + cell(s.reductionMoyenne, \' %\') + \'</td>\' +\n  \'<td style="padding:6px 10px;border:1px solid #ddd;text-align:right">\' + cell(s.reductionMax, \' %\') + \'</td>\' +\n  \'<td style="padding:6px 10px;border:1px solid #ddd;text-align:right">\' + cell(s.prixMoyen, \' EUR\') + \'</td></tr>\'\n).join(\'\');\n\nconst alertes = [];\nif (d.statut === \'Collecte partielle\') {\n  alertes.push(\'Collecte partielle : \' + d.totalProduits + \' produits recuperes sur \' + (d.totalAnnonce || \'?\') + \' annonces par Boulanger, via \' + (d.pagesOk || 0) + \' page(s) de categorie. Boulanger ne rend que 40 fiches par page et ne propose pas de pagination par URL, les references restantes ne sont donc pas accessibles.\');\n}\nif (!d.semainePrecedente) {\n  alertes.push(\'Aucune collecte precedente trouvee : la comparaison hebdomadaire sera disponible a partir de la semaine prochaine.\');\n} else {\n  alertes.push(\'Comparaison effectuee avec la collecte du \' + d.semainePrecedente + \' (\' + d.nbCollectesHistoriques + \' collecte(s) dans l historique).\');\n}\nif (d.erreurs && d.erreurs.length) alertes.push(\'Detail des pages : \' + d.erreurs.slice(0, 8).join(\' | \'));\n\nconst reponseIA = $(\'Analyse IA\').first().json;\nconst texteAnalyse = ((reponseIA && (reponseIA.content || (reponseIA.message && reponseIA.message.content))) || \'Analyse indisponible.\').toString().trim();\n\nconst html = \'<html><body style="font-family:Arial,Helvetica,sans-serif;color:#222;font-size:14px">\' +\n\'<h2 style="margin-bottom:4px">Veille concurrentielle - Refrigerateurs</h2>\' +\n\'<p style="margin-top:0;color:#666">Enseigne : \' + echapper(d.enseigne) + \'</p>\' +\n\'<h3>Resume</h3>\' +\n\'<table cellpadding="4" cellspacing="0"><tr><td><strong>Date de collecte</strong></td><td>\' + echapper(d.dateCollecte) + \'</td></tr>\' +\n\'<tr><td><strong>Enseigne</strong></td><td>\' + echapper(d.enseigne) + \'</td></tr>\' +\n\'<tr><td><strong>Nombre de produits</strong></td><td>\' + d.totalProduits + \'</td></tr>\' +\n\'<tr><td><strong>Statut de la collecte</strong></td><td>\' + echapper(d.statut) + \'</td></tr></table>\' +\n\'<h3>Statistiques par marque</h3>\' +\n\'<table cellpadding="0" cellspacing="0" style="border-collapse:collapse">\' +\n\'<tr style="background:#f0f0f0"><th style="padding:6px 10px;border:1px solid #ddd;text-align:left">Marque</th>\' +\n\'<th style="padding:6px 10px;border:1px solid #ddd">Produits</th>\' +\n\'<th style="padding:6px 10px;border:1px solid #ddd">Promotions</th>\' +\n\'<th style="padding:6px 10px;border:1px solid #ddd">Taux promo</th>\' +\n\'<th style="padding:6px 10px;border:1px solid #ddd">Reduction moyenne</th>\' +\n\'<th style="padding:6px 10px;border:1px solid #ddd">Reduction max</th>\' +\n\'<th style="padding:6px 10px;border:1px solid #ddd">Prix moyen</th></tr>\' +\n(lignesHtml || \'<tr><td colspan="7" style="padding:8px">Aucune donnee.</td></tr>\') + \'</table>\' +\n\'<h3>Analyse</h3><p>\' + echapper(texteAnalyse).replace(/\\n/g, \'<br>\') + \'</p>\' +\n\'<h3>Alertes</h3><ul>\' + alertes.map((a) => \'<li>\' + echapper(a) + \'</li>\').join(\'\') + \'</ul>\' +\n\'<p style="color:#999;font-size:12px">Genere automatiquement. Donnees lues directement dans le HTML du site, non estimees.</p>\' +\n\'</body></html>\';\n\nreturn [{ json: { ...d, html: html, sujet: \'Veille refrigerateurs - \' + d.enseigne + \' - \' + d.statut + \' - \' + d.totalProduits + \' produits\' } }];' }, position: [2016, 0], notes: 'Produit le HTML du message selon la section 10 de la spec. Reference explicite au noeud Analyse IA car celui ci renvoie la reponse du modele.', notesInFlow: true, executeOnce: true }
});

